/**
 * tests/adversarial-m3-scrolling-trap.js - Empirical Adversarial Test Harness for Milestone 3
 * 
 * Deeply stress-tests:
 * 1. Shelf Horizontal Auto-Scroll Geometry:
 *    - Left margin boundary enforcement (>= 96px)
 *    - Right margin boundary enforcement (<= 1824px on 1920px canvas)
 *    - Deadband invariance (no unnecessary scrolling for in-view items)
 *    - First-item scrollLeft reset (index 0 / first child)
 *    - Rail scrollWidth clamping & peek offset behavior
 *    - Multi-card sequential navigation viewport coordinate verification
 *    - Rapid key repeat throttling behavior switch ('auto' vs 'smooth')
 * 
 * 2. Viewport Vertical Auto-Scroll Geometry:
 *    - Fixed header clearance (top >= 104px, preventing occlusion by 84px header)
 *    - Bottom TV safe area enforcement (bottom <= 1026px)
 *    - Content shelf vs generic grid item scroll calculations
 *    - Header and hero focus scroll resets (scrollTop -> 0)
 *    - Deadband invariance
 *    - Multi-row vertical journey occlusion check
 * 
 * 3. Modal Focus Trapping on Virtual Keyboard (.tv-keyboard-container):
 *    - Active trap state & getCandidates() isolation
 *    - Cardinal 2D D-pad navigation inside keyboard
 *    - Perimeter containment: ArrowUp from top row (no escape to header/input)
 *    - Perimeter containment: ArrowDown from bottom row (no escape to search results)
 *    - Perimeter containment: ArrowLeft/ArrowRight from edges
 *    - Programmatic setFocus() rejection for outside elements during active trap
 *    - Untrap release & candidate restoration
 *    - Event lifecycle (trap, untrap, deadend events)
 *    - Trap cleanup on engine destroy
 */

const fs = require('fs');
const path = require('path');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// 2. Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalTests = 0;
let passedTests = 0;
let failedTests = 0;
const failureList = [];

function assert(condition, message) {
  if (!condition) {
    throw new Error(message || 'Adversarial assertion failed');
  }
}

function runTest(category, name, fn) {
  totalTests++;
  const idStr = totalTests.toString().padStart(2, '0');
  process.stdout.write(`  [Test ${idStr}] [${category}] ${name} ... `);
  try {
    fn();
    passedTests++;
    console.log(`${C.green}${C.bold}✔ PASS${C.reset}`);
  } catch (err) {
    failedTests++;
    failureList.push({ id: totalTests, category, name, error: err.message, stack: err.stack });
    console.log(`${C.red}${C.bold}✖ FAIL${C.reset}`);
    console.log(`      ${C.red}Defect: ${err.message}${C.reset}`);
  }
}

// 3. Layout and Scroll Mock Infrastructure
function installScrollMocks(window) {
  window.Element.prototype.scrollIntoView = function (options) {
    this._lastScrollIntoView = options || true;
  };

  window.Element.prototype.scrollTo = function (x, y) {
    if (typeof x === 'object') {
      this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
      this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
      this._lastScrollBehavior = x.behavior || 'auto';
    } else {
      this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
      this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
    }
  };
}

function setupLayoutMock(window) {
  function makeRect(left, top, width, height) {
    return {
      left: left,
      top: top,
      width: width,
      height: height,
      right: left + width,
      bottom: top + height,
      x: left,
      y: top
    };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    // 1. Dynamic override via data-mock-rect attribute
    var mockAttr = this.getAttribute('data-mock-rect');
    if (mockAttr) {
      try {
        var parsed = JSON.parse(mockAttr);
        return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
      } catch (err) {}
    }

    // 2. Elements with display: none or inside non-active views have zero geometry
    var view = this.closest('.view');
    if (view && !view.classList.contains('active')) {
      return makeRect(0, 0, 0, 0);
    }
    if (this.style.display === 'none') {
      return makeRect(0, 0, 0, 0);
    }

    // 3. Known component mappings
    var id = this.id;
    if (id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (id === 'hero-list-btn') return makeRect(433, 460, 140, 56);
    if (id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (id === 'details-trailer-btn') return makeRect(292, 450, 160, 56);
    if (id === 'player-back-btn') return makeRect(96, 54, 56, 56);
    if (id === 'osd-play-btn') return makeRect(912, 940, 96, 96);
    if (id === 'osd-rewind-btn') return makeRect(840, 940, 56, 56);
    if (id === 'osd-forward-btn') return makeRect(1024, 940, 56, 56);

    // Header brand & nav items
    if (this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
    if (this.classList.contains('nav-pill-item')) {
      var route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    // Content Shelves
    if (this.classList.contains('content-shelf')) {
      var parentShelves = this.parentElement ? Array.from(this.parentElement.children) : [];
      var shelfIdx = parentShelves.indexOf(this);
      return makeRect(0, 560 + Math.max(0, shelfIdx) * 400, 1920, 380);
    }

    // Poster cards
    if (this.classList.contains('card-poster')) {
      var parent = this.parentElement;
      var index = parent ? Array.from(parent.children).indexOf(this) : 0;
      var grid = this.closest('.content-grid-6col');
      if (grid) {
        var col = index % 6;
        var row = Math.floor(index / 6);
        return makeRect(96 + col * 288, 180 + row * 424, 264, 396);
      }
      var isShelf1 = parent && (parent.closest('.content-shelf:nth-of-type(2)') || parent.closest('#shelf-trending'));
      var top = isShelf1 ? 680 : 1060;
      return makeRect(96 + index * 244, top, 220, 330);
    }

    // Provider cards
    if (this.classList.contains('card-provider')) {
      var pIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(96 + pIndex * 184, 560, 160, 80);
    }

    // Episode cards
    if (this.classList.contains('card-episode')) {
      var epIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(96 + epIndex * 344, 670, 320, 180);
    }

    // Filter pills
    if (this.classList.contains('filter-pill')) {
      var fIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(96 + fIndex * 130, 110, 110, 44);
    }

    // Virtual keyboard keys: row layout
    if (this.classList.contains('key-btn')) {
      var rowEl = this.closest('.keyboard-row');
      var rIdx = rowEl && rowEl.parentElement ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
      var cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;

      // Special width for space/backspace/clear
      var w = 50;
      var h = 50;
      if (this.classList.contains('key-space')) {
        w = 320;
      } else if (this.classList.contains('key-wide')) {
        w = 140;
      }
      var xOffset = 96 + cIdx * 60;
      if (rIdx === 4) { // Row 5 actions
        if (cIdx === 1) xOffset = 96 + 330;
        if (cIdx === 2) xOffset = 96 + 330 + 150;
      }
      return makeRect(xOffset, 220 + rIdx * 60, w, h);
    }

    // Default fallback
    return makeRect(96, 100, 100, 40);
  };
}

function createHarness(route = 'home') {
  const htmlPath = path.resolve(__dirname, '../app/index.html');
  const configPath = path.resolve(__dirname, '../app/js/config.js');
  const navPath = path.resolve(__dirname, '../app/js/navigation.js');
  const appPath = path.resolve(__dirname, '../app/js/app.js');

  const html = fs.readFileSync(htmlPath, 'utf8');
  const dom = new JSDOM(html, {
    url: 'http://localhost/#' + route,
    runScripts: 'outside-only'
  });
  const { window } = dom;

  window.__TEST_M3__ = true;
  installScrollMocks(window);
  setupLayoutMock(window);

  window.eval(fs.readFileSync(configPath, 'utf8'));
  window.eval(fs.readFileSync(navPath, 'utf8'));
  window.eval(fs.readFileSync(appPath, 'utf8'));

  window.CinejoyApp.init();

  return { dom, window, app: window.CinejoyApp, nav: window.SpatialNav };
}

console.log(`\n${C.bold}${C.cyan}========================================================================${C.reset}`);
console.log(`${C.bold}${C.cyan}   CINEJOY-WEBOS: M3 ADVERSARIAL STRESS HARNESS                         ${C.reset}`);
console.log(`${C.bold}${C.cyan}   Shelf Scroll Boundaries, Viewport Clearance, and Modal Trapping      ${C.reset}`);
console.log(`${C.bold}${C.cyan}========================================================================${C.reset}\n`);

// ============================================================================
// SUITE 1: Horizontal Shelf Auto-Scroll Geometry (96px Left, 1824px Right)
// ============================================================================
console.log(`${C.bold}${C.yellow}▶ SUITE 1: Horizontal Shelf Auto-Scroll Geometry${C.reset}`);

runTest('ShelfScroll', 'Right Boundary: Element clipped beyond 1824px triggers clamping scroll', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 0;
  rail.scrollWidth = 4000;
  rail.clientWidth = 1920;

  // Add an off-screen card at right edge 2100px
  const card = window.document.createElement('div');
  card.className = 'card-poster';
  card.setAttribute('data-nav', 'true');
  card.setAttribute('data-nav-index', '8');
  card.setAttribute('data-mock-rect', JSON.stringify({ left: 1880, top: 680, width: 220, height: 330 })); // right = 2100
  rail.appendChild(card);

  nav.setFocus(card);

  // dRight = 2100 - 1824 = 276. targetRight = 0 + 276 + 48 = 324.
  // Effective new right on screen = 2100 - 324 = 1776px, which is <= 1824px (leaves 48px peek room)!
  assert(rail.scrollLeft >= 276, `Expected rail.scrollLeft >= 276, got ${rail.scrollLeft}`);
  const effectiveScreenRight = 2100 - rail.scrollLeft;
  assert(effectiveScreenRight <= 1824, `Element right edge (${effectiveScreenRight}px) must be <= 1824px safe margin`);
  assert(effectiveScreenRight - 220 >= 96, `Element left edge (${effectiveScreenRight - 220}px) must be >= 96px safe margin`);
});

runTest('ShelfScroll', 'Extreme Right Boundary: Element far off-screen (4000px)', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 500;
  rail.scrollWidth = 5000;
  rail.clientWidth = 1920;

  const cardFar = window.document.createElement('div');
  cardFar.className = 'card-poster';
  cardFar.setAttribute('data-nav', 'true');
  cardFar.setAttribute('data-nav-index', '15');
  cardFar.setAttribute('data-mock-rect', JSON.stringify({ left: 3780, top: 680, width: 220, height: 330 })); // right = 4000
  rail.appendChild(cardFar);

  nav.setFocus(cardFar);

  // dRight = 4000 - 1824 = 2176. targetRight = 500 + 2176 + 48 = 2724.
  // Effective right on screen = (4000 + 500) - 2724 = 1776px <= 1824px.
  assert(rail.scrollLeft >= (500 + (4000 - 1824)), 'Must scroll right sufficiently to contain element within 1824px');
});

runTest('ShelfScroll', 'Left Boundary: Element clipped below 96px triggers scrollLeft reduction', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 800;

  // Card with left at 20px (clipped by 76px below 96px margin)
  const cardLeft = window.document.createElement('div');
  cardLeft.className = 'card-poster';
  cardLeft.setAttribute('data-nav', 'true');
  cardLeft.setAttribute('data-nav-index', '2');
  cardLeft.setAttribute('data-mock-rect', JSON.stringify({ left: 20, top: 680, width: 220, height: 330 }));
  rail.appendChild(cardLeft);

  nav.setFocus(cardLeft);

  // dLeft = 96 - 20 = 76. new scrollLeft = 800 - 76 = 724.
  // Effective screen left = 20 + 76 = 96px!
  assert.strictEqual(rail.scrollLeft, 724, `Expected rail.scrollLeft to be 724, got ${rail.scrollLeft}`);
  const effectiveScreenLeft = 20 + (800 - rail.scrollLeft);
  assert(effectiveScreenLeft >= 96, `Element left edge (${effectiveScreenLeft}px) must be >= 96px`);
  assert(effectiveScreenLeft + 220 <= 1824, `Element right edge (${effectiveScreenLeft + 220}px) must be <= 1824px`);
});

runTest('ShelfScroll', 'Negative Left Coordinate: Element scrolled heavily off-screen to the left (-150px)', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 1000;

  const cardNeg = window.document.createElement('div');
  cardNeg.className = 'card-poster';
  cardNeg.setAttribute('data-nav', 'true');
  cardNeg.setAttribute('data-nav-index', '1');
  cardNeg.setAttribute('data-mock-rect', JSON.stringify({ left: -150, top: 680, width: 220, height: 330 }));
  rail.appendChild(cardNeg);

  nav.setFocus(cardNeg);

  // dLeft = 96 - (-150) = 246. new scrollLeft = 1000 - 246 = 754.
  assert.strictEqual(rail.scrollLeft, 754, `Expected rail.scrollLeft = 754, got ${rail.scrollLeft}`);
});

runTest('ShelfScroll', 'Deadband: Element fully inside [96, 1824] produces zero scroll jump', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 300;

  const cardInside = window.document.createElement('div');
  cardInside.className = 'card-poster';
  cardInside.setAttribute('data-nav', 'true');
  cardInside.setAttribute('data-nav-index', '3');
  cardInside.setAttribute('data-mock-rect', JSON.stringify({ left: 500, top: 680, width: 220, height: 330 })); // right = 720
  rail.appendChild(cardInside);

  nav.setFocus(cardInside);
  assert.strictEqual(rail.scrollLeft, 300, `ScrollLeft must remain 300 in deadband, got ${rail.scrollLeft}`);
});

runTest('ShelfScroll', 'First Element Reset: data-nav-index="0" resets scrollLeft to 0', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 650;

  const firstCard = rail.querySelector('.card-poster[data-nav-index="0"]') || rail.firstElementChild;
  assert(firstCard, 'First card must exist in rail');
  nav.setFocus(firstCard);

  assert.strictEqual(rail.scrollLeft, 0, `Focusing first card must reset rail.scrollLeft to 0, got ${rail.scrollLeft}`);
