  assert.strictEqual(pane.scrollTop, 280, `Expected pane.scrollTop = 280, got ${pane.scrollTop}`);
});

runTest('ViewportScroll', 'Bottom Safe Area: Card bottom clipped past 1026px scrolls down', () => {
  const { window, nav } = createHarness('home');
