});

runTest('ViewportScroll', 'Generic Grid Item: Top occluded (< 104px) scrolls with 24px safety buffer', () => {
  const { window, app, nav } = createHarness('movies');
  const pane = window.document.querySelector('#view-movies .view-scroll-pane');
  pane.scrollTop = 500;

  const card = window.document.createElement('div');
  card.className = 'card-poster';
  card.setAttribute('data-nav', 'true');
  // Top at 60px
  card.setAttribute('data-mock-rect', JSON.stringify({ left: 96, top: 60, width: 264, height: 396 }));
  window.document.querySelector('#view-movies .content-grid-6col').appendChild(card);

  nav.setFocus(card);

  // diffTop = 104 - 60 = 44. new scrollTop = 500 - 44 - 24 = 432.
  // Effective new top = 60 + (500 - 432) = 128px >= 104px!
  assert.strictEqual(pane.scrollTop, 432, `Expected pane.scrollTop = 432, got ${pane.scrollTop}`);
  const effectiveTop = 60 + (500 - pane.scrollTop);
  assert(effectiveTop >= 104, `Effective top (${effectiveTop}px) must be >= 104px`);
});

