runTest('FocusTrap', 'Trap Activation & State: isTrapped() returns true, activeTrap matches container', () => {
  const { window, app, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  assert(kbContainer, '.tv-keyboard-container must exist in search view');

  assert.strictEqual(nav.isTrapped(), false, 'isTrapped() must initially be false');

  nav.trap(kbContainer);
  assert.strictEqual(nav.isTrapped(), true, 'isTrapped() must be true after trap()');
