runTest('FocusTrap', 'Candidate Isolation: getCandidates() discovers ONLY virtual keyboard keys', () => {
  const { window, app, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);

  const candidates = nav.getCandidates();
  assert(candidates.length > 0, 'Virtual keyboard must have navigable candidates');

  // Verify EVERY single candidate is inside .tv-keyboard-container
  for (let i = 0; i < candidates.length; i++) {
    const cand = candidates[i];
    assert(kbContainer.contains(cand), `Candidate ${cand.outerHTML} must be contained inside .tv-keyboard-container`);
    assert.strictEqual(cand.getAttribute('data-nav-group'), 'keyboard', 'Candidate must belong to keyboard nav group');
  }

  // Header items and search result cards must NOT be candidates
  const headerPill = window.document.querySelector('.nav-pill-item');
  const searchCard = window.document.querySelector('.card-poster');
  assert(!candidates.includes(headerPill), 'Header pill must not be in candidates when trapped');
  assert(!candidates.includes(searchCard), 'Search result card must not be in candidates when trapped');
});

runTest('FocusTrap', 'Trap string selector support: trap(".tv-keyboard-container")', () => {
  const { window, nav } = createHarness('search');
  nav.trap('.tv-keyboard-container');
  assert.strictEqual(nav.isTrapped(), true);
  const candidates = nav.getCandidates();
  assert(candidates.length > 0);
  assert(candidates.every(c => c.closest('.tv-keyboard-container')));
});

runTest('FocusTrap', 'Trapped 2D D-pad Navigation: Stepping across keys inside keyboard', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);

  const key1 = kbContainer.querySelector('[data-key="1"]');
  const key2 = kbContainer.querySelector('[data-key="2"]');
  const keyQ = kbContainer.querySelector('[data-key="Q"]');
  assert(key1 && key2 && keyQ, 'Keyboard keys 1, 2, Q must exist');

  nav.setFocus(key1);
  assert.strictEqual(nav.getCurrentFocus(), key1);

  // Move right to '2'
  nav.resetThrottle();
  const movedRight = nav.move('right');
  assert.strictEqual(movedRight, key2, `Expected move right to land on '2', got ${movedRight && movedRight.getAttribute('data-key')}`);

  // Move down from '2' to 'W'
  nav.resetThrottle();
  const movedDown = nav.move('down');
  assert.strictEqual(movedDown.getAttribute('data-key'), 'W', `Expected move down to land on 'W', got ${movedDown && movedDown.getAttribute('data-key')}`);
});

runTest('FocusTrap', 'Perimeter Containment: ArrowUp from Row 1 cannot escape to header or search input', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);

  const key5 = kbContainer.querySelector('[data-key="5"]');
  nav.setFocus(key5);

  let deadendTriggered = false;
  nav.on('deadend', (e) => {
    if (e.direction === 'up') deadendTriggered = true;
  });

  nav.resetThrottle();
  const moved = nav.move('up');

  assert.strictEqual(moved, null, 'Moving up from Row 1 while trapped must return null (deadend)');
  assert.strictEqual(nav.getCurrentFocus(), key5, 'Focus must remain on key 5');
  assert.strictEqual(deadendTriggered, true, 'Deadend event must be emitted on blocked movement');
});

runTest('FocusTrap', 'Perimeter Containment: ArrowDown from Row 5 cannot escape to search results', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);

  const keySpace = kbContainer.querySelector('[data-key="SPACE"]');
  nav.setFocus(keySpace);

