    if (e.direction === 'down') deadendTriggered = true;
  });

  nav.resetThrottle();
  const moved = nav.move('down');

  assert.strictEqual(moved, null, 'Moving down from bottom row while trapped must return null');
  assert.strictEqual(nav.getCurrentFocus(), keySpace, 'Focus must remain on SPACE key');
  assert.strictEqual(deadendTriggered, true, 'Deadend event must be emitted on blocked downward movement');
});

runTest('FocusTrap', 'Perimeter Containment: ArrowLeft from leftmost column cannot escape', () => {
