  const moved = nav.move('left');
  assert.strictEqual(moved, null, 'Moving left from key A must return null');
  assert.strictEqual(nav.getCurrentFocus(), keyA, 'Focus must remain on key A');
});

runTest('FocusTrap', 'Perimeter Containment: ArrowRight from rightmost column cannot escape', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);

  const keyP = kbContainer.querySelector('[data-key="P"]');
