runTest('FocusTrap', 'Programmatic setFocus rejection for elements outside trap', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);

  const key1 = kbContainer.querySelector('[data-key="1"]');
  nav.setFocus(key1);

  const headerPill = window.document.querySelector('.nav-pill-item[data-route="search"]');
  const searchCard = window.document.querySelector('#search-results-grid .card-poster');

  // Attempt to focus header pill
  const resHeader = nav.setFocus(headerPill);
  assert.strictEqual(resHeader, false, 'setFocus on header pill must return false when trapped');
  assert.strictEqual(nav.getCurrentFocus(), key1, 'Focus must remain on key 1');

  // Attempt to focus search card
  const resCard = nav.setFocus(searchCard);
  assert.strictEqual(resCard, false, 'setFocus on search card must return false when trapped');
  assert.strictEqual(nav.getCurrentFocus(), key1, 'Focus must remain on key 1');
});

runTest('FocusTrap', 'Untrap Release: Restores full navigation to header and search results', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);
  assert.strictEqual(nav.isTrapped(), true);

  let untrapEventFired = false;
  nav.on('untrap', (e) => {
    untrapEventFired = true;
    assert.strictEqual(e.container, kbContainer);
  });

  nav.untrap();
  assert.strictEqual(nav.isTrapped(), false, 'isTrapped() must be false after untrap()');
  assert.strictEqual(untrapEventFired, true, 'untrap event must be emitted');

  const candidates = nav.getCandidates();
  const headerPill = window.document.querySelector('.nav-pill-item[data-route="search"]');
  const searchCard = window.document.querySelector('#search-results-grid .card-poster');

  assert(candidates.includes(headerPill), 'Candidates must include header items after untrap');
  assert(candidates.includes(searchCard), 'Candidates must include search result cards after untrap');

  // Programmatic setFocus now succeeds
  const res = nav.setFocus(searchCard);
  assert.strictEqual(res, true, 'setFocus on search card must succeed after untrap');
  assert.strictEqual(nav.getCurrentFocus(), searchCard);
});

runTest('FocusTrap', 'Engine Destroy Cleans Up Active Trap', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);
  assert.strictEqual(nav.isTrapped(), true);

  nav.destroy();
  assert.strictEqual(nav.isTrapped(), false, 'destroy() must reset activeTrap');
});

