runTest('ShelfScroll', 'Max Clamping: targetRight clamped by (scrollWidth - clientWidth)', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 1000;
  Object.defineProperty(rail, 'scrollWidth', { value: 3000, configurable: true });
  Object.defineProperty(rail, 'clientWidth', { value: 1920, configurable: true }); // max scroll is 3000 - 1920 = 1080

  const lastCard = window.document.createElement('div');
  lastCard.className = 'card-poster';
  lastCard.setAttribute('data-nav', 'true');
  lastCard.setAttribute('data-nav-index', '12');
  lastCard.setAttribute('data-mock-rect', JSON.stringify({ left: 2900, top: 680, width: 220, height: 330 }));
  rail.appendChild(lastCard);

  nav.setFocus(lastCard);
  assert.strictEqual(rail.scrollLeft, 1080, `rail.scrollLeft must be clamped to max 1080, got ${rail.scrollLeft}`);
});

runTest('ShelfScroll', 'Rapid repeat hammering switches scroll behavior to "auto"', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  rail.scrollLeft = 0;

  const card = window.document.createElement('div');
  card.className = 'card-poster';
  card.setAttribute('data-nav', 'true');
  card.setAttribute('data-nav-index', '5');
  card.setAttribute('data-mock-rect', JSON.stringify({ left: 1900, top: 680, width: 220, height: 330 }));
  rail.appendChild(card);

  // Simulate TV remote key repeat at 70ms intervals (between 60ms throttle and 120ms burst window)
  let simulatedTime = 10000;
  const origDateNow = window.Date.now;
  window.Date.now = () => simulatedTime;

  const evt = () => new window.KeyboardEvent('keydown', { key: 'ArrowRight', keyCode: 39, bubbles: true, cancelable: true });

  // 4 rapid repeats at 70ms intervals
  window.dispatchEvent(evt());
  simulatedTime += 70;
  window.dispatchEvent(evt());
  simulatedTime += 70;
  window.dispatchEvent(evt());
  simulatedTime += 70;
  window.dispatchEvent(evt());

  nav.setFocus(card);
  assert.strictEqual(rail._lastScrollBehavior, 'auto', `Rapid key presses must use 'auto' scroll behavior, got ${rail._lastScrollBehavior}`);

  window.Date.now = origDateNow;
});

