runTest('FocusTrap', 'Engine Destroy Cleans Up Active Trap', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);
  assert.strictEqual(nav.isTrapped(), true);

  nav.destroy();
  assert.strictEqual(nav.isTrapped(), false, 'destroy() must reset activeTrap');
});

// ============================================================================
// SUITE 4: Multi-Axial Edge Cases & Boundary Stress
// ============================================================================
console.log(`\n${C.bold}${C.yellow}▶ SUITE 4: Multi-Axial Edge Cases & Boundary Stress${C.reset}`);

runTest('MultiAxial', 'Simultaneous Horizontal Clipping (X > 1824) and Vertical Occlusion (Y < 104)', () => {
  const { window, nav } = createHarness('home');
  const rail = window.document.querySelector('.shelf-rail');
  const pane = window.document.querySelector('#view-home .view-scroll-pane');
  rail.scrollLeft = 0;
  pane.scrollTop = 400;

  const shelf = window.document.querySelector('#view-home .content-shelf:nth-of-type(2)');
  const card = window.document.createElement('div');
  card.className = 'card-poster';
  card.setAttribute('data-nav', 'true');
  card.setAttribute('data-nav-index', '9');
  // Right at 2000px (> 1824px), Top at 50px (< 104px)
  card.setAttribute('data-mock-rect', JSON.stringify({ left: 1780, top: 50, width: 220, height: 330 }));
  shelf.querySelector('.shelf-rail').appendChild(card);

  nav.setFocus(card);

  // Both scroll containers must independently adjust
  assert(rail.scrollLeft >= (2000 - 1824), 'Rail must scroll right to bring card within 1824px');
  assert.strictEqual(pane.scrollTop, 346, 'Pane must scroll up to bring card top to 104px');
  const effectiveScreenRight = 2000 - rail.scrollLeft;
  const effectiveScreenTop = 50 + (400 - pane.scrollTop);
  assert(effectiveScreenRight <= 1824, `Effective right (${effectiveScreenRight}px) <= 1824px`);
  assert(effectiveScreenTop >= 104, `Effective top (${effectiveScreenTop}px) >= 104px`);
});

runTest('MultiAxial', 'Trapped Enter Key executes click on virtual key without leaking focus', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  nav.trap(kbContainer);

  const keyQ = kbContainer.querySelector('[data-key="Q"]');
  nav.setFocus(keyQ);

  let clicked = false;
  keyQ.addEventListener('click', () => { clicked = true; });

  // Send Enter/OK key (keyCode 13)
  const enterEvt = new window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true, cancelable: true });
  window.dispatchEvent(enterEvt);

  assert.strictEqual(clicked, true, 'Click handler on focused key must be executed on Enter');
  assert.strictEqual(nav.isTrapped(), true, 'Focus trap must remain active');
  assert.strictEqual(nav.getCurrentFocus(), keyQ, 'Focus must remain on the key');
});

runTest('MultiAxial', 'Sequential Trap Switching: trap(containerA) then trap(containerB)', () => {
  const { window, nav } = createHarness('search');
  const kbContainer = window.document.querySelector('.tv-keyboard-container');
  const resultsGrid = window.document.querySelector('#search-results-grid');

  nav.trap(kbContainer);
  assert.strictEqual(nav.isTrapped(), true);
  assert(nav.getCandidates().every(c => kbContainer.contains(c)));

  // Switch trap to resultsGrid
  nav.trap(resultsGrid);
  assert.strictEqual(nav.isTrapped(), true);
  const newCandidates = nav.getCandidates();
  assert(newCandidates.length > 0);
  assert(newCandidates.every(c => resultsGrid.contains(c)));

  // Untrap clears completely
  nav.untrap();
  assert.strictEqual(nav.isTrapped(), false);
});

runTest('MultiAxial', 'Null trap and untrap idempotency', () => {
  const { window, nav } = createHarness('search');

  // Calling untrap when not trapped
  nav.untrap();
  assert.strictEqual(nav.isTrapped(), false);

  // Calling trap(null)
  nav.trap(null);
  assert.strictEqual(nav.isTrapped(), false);

  // Calling trap with non-existent selector
  nav.trap('#non-existent-modal-id-404');
  assert.strictEqual(nav.isTrapped(), false);
});

runTest('MultiAxial', 'Element outside scroll containers executes autoScroll without exceptions', () => {
  const { window, nav } = createHarness('home');
  const orphanBtn = window.document.createElement('button');
  orphanBtn.setAttribute('data-nav', 'true');
  orphanBtn.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 50, height: 50 }));
  window.document.body.appendChild(orphanBtn);

  // Must not throw even though not in a shelf-rail or view-scroll-pane
  nav.setFocus(orphanBtn);
  assert.strictEqual(nav.getCurrentFocus(), orphanBtn);
});

